def transform(grid):
    out = [row[:] for row in grid]
    # Colored markers on the horizontal 1-line grow upward: 2 has height 4,
    # 8 has height 3, with 1-colored shafts and the marker color at the tip.
    base = next((r for r, row in enumerate(grid) if 2 in row or 8 in row), None)
    if base is None:
        return out
    for c, color in enumerate(grid[base]):
        height = {2: 4, 8: 3}.get(color, 0)
        for d in range(1, min(height, base + 1)):
            out[base - d][c] = 1
        if height and base - height >= 0:
            out[base - height][c] = color
    return out
